// 😀 semantic fixture
String? subject(String? v) => v ?? 'fallback';
void main() {
  try {
    if (!(subject(null) == 'fallback' && subject('x') == 'x')) throw StateError('MUTATION_OBSERVED');
  } catch (_) {
    throw StateError('MUTATION_OBSERVED');
  }
}

